import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    优化后的模型：保留Linear和AvgPool1d，由自定义AscendC内核加速GELU，随后进行缩放与最大池化。
    """
    def __init__(self, in_features, out_features, pool_kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.matmul = torch.nn.Linear(in_features, out_features)
        self.avg_pool = torch.nn.AvgPool1d(kernel_size=pool_kernel_size)
        self.scale_factor = scale_factor

    def forward(self, x):
        # 线性变换
        x = self.matmul(x)
        # 平均池化（按通道1维度处理）
        x = self.avg_pool(x.unsqueeze(1)).squeeze(1)
        # 自定义AscendC内核执行GELU
        x = custom_ops_lib.matmul_avg_pool_gelu_scale_max_custom(x)
        # 缩放
        x = x * self.scale_factor
        # 沿特征维取最大值
        x = torch.max(x, dim=1).values
        return x
